internal final class METMarkupTransFormEventHandler
{
}

Method.Source:
/// <summary>
/// EventHandler for formControlStr MarkupTrans_MarkupCode1
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormControlEventHandler(formControlStr(MarkupTrans, MarkupTrans_MarkupCode1), FormControlEventType::Modified), 
 FormControlEventHandler(formControlStr(MarkupTrans, MarkupTrans_METAdvancedCalculation), FormControlEventType::Modified)]
public static void MarkupTrans_MarkupCode1_OnModified(FormControl sender, FormControlEventArgs e)
{
    FormDataSource      markupTrans_DS  = sender.formRun().dataSource(formDataSourceStr(MarkupTrans, MarkupTrans));

    METMarkupTransFormEventHandler::markupTransModified(markupTrans_DS);
}

/// <summary>
/// EventHandler for form datasource MarkupTrans.
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormDataSourceEventHandler(formDataSourceStr(MarkupTrans, MarkupTrans), FormDataSourceEventType::SelectionChanged)]
public static void MarkupTrans_OnSelectionChanged(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSource      markupTrans_DS  = sender;

    METMarkupTransFormEventHandler::markupTransModified(markupTrans_DS);
}

/// <summary>
/// Common method to enabled/disbale chargesMethod field
/// </summary>
/// <param name = "_markupTransDS">Datasource</param>
public static void markupTransModified(FormDataSource _markupTransDS)
{
    MarkupTrans         markupTransloc  = _markupTransDS.cursor();
    boolean             isTrue = !(markupTransloc.MarkupCode == '' || (markupTransloc.MarkupCode != '' && !markupTransloc.METAdvancedCalculation));

    _markupTransDS.object(fieldNum(MarkupTrans, METChargesMethod)).enabled(isTrue);
}
